#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int r,c;scanf("%d %d",&r,&c);
vector<vector<int>>g(r,vector<int>(c));
for(int i=0;i<r;++i)for(int j=0;j<c;++j)scanf("%d",&g[i][j]);
vector<vector<int>>dp(r+1,vector<int>(c+1,0));
int best=0;
for(int i=1;i<=r;++i)for(int j=1;j<=c;++j)
if(g[i-1][j-1]==1){
dp[i][j]=min({dp[i-1][j],dp[i][j-1],dp[i-1][j-1]})+1;
best=max(best,dp[i][j]);}
printf("%d\n",best*best);return 0;}

